import java.util.*;
import java.util.concurrent.*;

public class CosmicCats {
    private final Set<String> identifiers;

    public CosmicCats(String... ids) {
        this.identifiers = new HashSet<>(Arrays.asList(ids));
    }

    public boolean containsIdentifier(String identifier) {
        return identifiers.contains(identifier);
    }

    public String getDisplay() {
        StringBuilder sb = new StringBuilder();
        for (String id : identifiers) {
            sb.append(id).append(" ");
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        Set<String> catsIdentifiers = new HashSet<>();
        catsIdentifiers.add("Whiskers");
        catsIdentifiers.add("Paws");
        catsIdentifiers.add("Claw");

        CosmicCats cosmicCats = new CosmicCats(catsIdentifiers.toArray(new String[0]));
        ExecutorService executor = Executors.newFixedThreadPool(3);

        for (String identifier : catsIdentifiers) {
            if (cosmicCats.containsIdentifier(identifier)) {
                executor.submit(() -> System.out.println("The Cosmic Cat with identifier " + identifier + " is part of the bundle."));
            } else {
                executor.submit(() -> System.out.println("The Cosmic Cat with identifier " + identifier + " is not part of the bundle."));
            }
        }

        executor.shutdown();
    }
}

public class CosmicCats {
    private final Set<String> identifiers;

    public CosmicCats(String... ids) {
        this.identifiers = new LinkedHashSet<>(Arrays.asList(ids));
    }

    public boolean isCatIdentifier(String identifier) {
        return identifiers.contains(identifier);
    }

    public String displayIdentifiers() {
        StringBuilder sb = new StringBuilder();
        for (String id : identifiers) {
            if (sb.length() > 0) {
                sb.append(", ");
            }
            sb.append(id);
        }
        return sb.toString();
    }

    public static void main(String[] args) throws InterruptedException {
        String[] catIdentifiers = {"Whiskers", "Paws", "Claw"};
        CosmicCats cats = new CosmicCats(catIdentifiers);

        ExecutorService executor = Executors.newFixedThreadPool(3);

