import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.locks.ReentrantReadWriteLock;
import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.StampedLock;

public class DelegatingDeviceTracker {
    private final ReadWriteLock lock = new ReentrantReadWriteLock();
    private final Map<String, Position> positions = new ConcurrentHashMap<>();

    public DelegatingDeviceTracker() {}

    public DelegatingDeviceTracker(Map<String, Position> initialPositions) {
        for (Map.Entry<String, Position> entry : initialPositions.entrySet()) {
            positions.put(entry.getKey(), entry.getValue());
        }
    }

    public Position getPosition(String gadgetId) {
        lock.readLock().lock();
        try {
            return positions.get(gadgetId);
        } finally {
            lock.readLock().unlock();
        }
    }

    public void updatePosition(String gadgetId, Position position) {
        if (!positions.containsKey(gadgetId)) {
            throw new IllegalArgumentException("Gadget not found");
        }

        lock.writeLock().lock();
        try {
            positions.put(gadgetId, position);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public Map<String, Position> getAllPositions() {
        return positions;
    }

    public static void main(String[] args) {
        Map<String, Position> initialPositions = new ConcurrentHashMap<>();
        initialPositions.put("G1", new Position(0, 0));
        initialPositions.put("G2", new Position(10, 10));

        DelegatingDeviceTracker tracker = new DelegatingDeviceTracker(initialPositions);

        ExecutorService service = Executors.newFixedThreadPool(2);

        for (int i = 1; i <= 5; i++) {
            Position newPosition;
            do {
                newPosition = new Position(tracker.getPosition("G" + i).x + 1, tracker.getPosition("G" + i).y + 1);
            } while (!tracker.updatePosition("G" + i, newPosition));
        }

        service.shutdown();
    }
}

