    }
}

import java.util.*;
import java.util.concurrent.*;

public class GadgetTracker {
    private final ConcurrentHashMap<String, Double> positions;

    public GadgetTracker() {
        this.positions = new ConcurrentHashMap<>();
    }

    public void addGadget(String id, double x) {
        if (positions.putIfAbsent(id, x) == null) {
            positions.replace(id, x, x); // allow only one update per ID
        }
    }

    public double getPosition(String id) {
        return positions.get(id);
    }

    public void updatePosition(String id, double x) {
        if (positions.replace(id, getPosition(id), x)) {
            // notify other threads that position has been updated
            synchronized (positions) {
                positions.notifyAll();
            }
        }
    }

    public Map<String, Double> getLivePositions() {
        return positions;
    }

    public static void main(String[] args) {
        GadgetTracker tracker = new GadgetTracker();
        tracker.addGadget("g1", 0);
        tracker.addGadget("g2", 1);

        Thread t1 = new Thread(() -> {
            for (int i = 0; i < 10; i++) {
                double x = rand.nextDouble() * 3 - 1;
                tracker.updatePosition("g1", x);
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            }
        });

        Thread t2 = new Thread(() -> {
            for (int i = 0; i < 10; i++) {
                double x = rand.nextDouble() * 3 - 1;
                tracker.updatePosition("g2", x);
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            }
        });

        ExecutorService exec = Executors.newFixedThreadPool(2);
        exec.submit(t1);
        exec.submit(t2);
        exec.shutdown();
    }
}

