public class DelegatingRobotTracker {
    private final Map<Integer, Coordinate> robotCoordinates;
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public DelegatingRobotTracker() {
        this.robotCoordinates = new ConcurrentHashMap<>();
    }

    public void addRobot(int id, Coordinate initialCoordinate) {
        lock.writeLock().lock();
        try {
            robotCoordinates.put(id, initialCoordinate);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void updateRobot(int id, Coordinate newCoordinate) {
        lock.writeLock().lock();
        try {
            if (!robotCoordinates.containsKey(id)) {
                throw new IllegalArgumentException("Robot not found");
            }
            robotCoordinates.put(id, newCoordinate);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public Map<Integer, Coordinate> getLiveRobotCoordinates() {
        return robotCoordinates;
    }

