import java.time.Duration;
import java.time.temporal.ChronoUnit;
import java.util.Random;
import java.util.concurrent.*;

public class LockerSystem {
    private static final Random RANDOM = new Random();

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        ParcelCount sourceParcelCount = new ParcelCount(10);
        ParcelCount targetParcelCount = new ParcelCount(5);
        int quantityToMove = 3;
        long timeoutDuration = Duration.ofSeconds(10).toMillis();
        ChronoUnit timeUnit = ChronoUnit.MILLIS;

        Locker sourceLocker = new Locker(sourceParcelCount);
        Locker targetLocker = new Locker(targetParcelCount);

        System.out.println("Starting move operation...");
        if (moveParcels(sourceLocker, targetLocker, quantityToMove, timeoutDuration, timeUnit)) {
            System.out.println("Move successful.");
        } else {
            System.out.println("Move failed due to timeout or insufficient items in source locker.");
        }
    }

    public static boolean moveParcels(Locker source, Locker target, int quantityToMove, long timeoutDuration, ChronoUnit timeUnit) {
        ExecutorService executor = Executors.newFixedThreadPool(3);

        try {
            Future<Void> sourceLockFuture = executor.submit(() -> {
                try {
                    source.lock();
                    Thread.sleep(calculateDelay(source));
                } catch (InterruptedException e) {
                    e.printStackTrace();
                    return null;
                }
                return null;
            });

            Future<Void> targetLockFuture = executor.submit(() -> {
                try {
                    target.lock();
                    Thread.sleep(calculateDelay(target));
                } catch (InterruptedException e) {
                    e.printStackTrace();
                    return null;
                }
                return null;
            });

            if (sourceLockFuture.get(timeoutDuration, timeUnit) != null && targetLockFuture.get(timeoutDuration, timeUnit) != null) {
                int sourceQuantity = sourceParcelCount.get();
                if (sourceQuantity >= quantityToMove) {
                    sourceParcelCount.addAndGet(-quantityToMove);
                    targetParcelCount.addAndGet(quantityToMove);
                    return true;
                } else {
                    throw new NotEnoughItemsException("Not enough items in the source locker to perform the move.");
                }
            } else {
                return false;
            }
        } finally {
            executor.shutdown();
        }
    }

    private static long calculateDelay(Locker locker) {
        long fixedDelay = 500;
        long maxRandomDelay = Duration.ofSeconds(2).toMillis();
        double randomFactor = RANDOM.nextDouble() + 1;
        return (long) (fixedDelay * randomFactor);
    }
}

class ParcelCount {
    private int items;

    public ParcelCount(int initialItems) {
        this.items = initialItems;
    }

    public int get() {
        return items;
    }

    public void addAndGet(int increment) {
        items += increment;
    }
}

class Locker {
    private final ParcelCount parcelCount;

    public Locker(ParcelCount parcelCount) {
        this.parcelCount = parcelCount;
    }

    public synchronized void lock() {
        try {
            wait();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }

    public synchronized void unlock() {
        notifyAll();
    }
}

class NotEnoughItemsException extends Exception {
    public NotEnoughItemsException(String message) {
        super(message);
    }
}

import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;

public class ParcelMover {
    public static void main(String[] args) {
        int sourceLockerId = 1;
        int targetLockerId = 2;
        int quantityToMove = 5;
        Duration timeoutDuration = Duration.ofSeconds(10);
        TimeUnit timeUnit = TimeUnit.SECONDS;

        LockerSource lockerSource = new LockerSource(sourceLockerId);
        LockerTarget lockerTarget = new LockerTarget(targetLockerId);

        try {
            ParcelMoverThread parcelMoverThread = new ParcelMoverThread(lockerSource, lockerTarget, quantityToMove, timeoutDuration, timeUnit);
            parcelMoverThread.run();

            if (parcelMoverThread.getResult()) {
                System.out.println("Parcels moved successfully.");
            } else {
                System.out.println("Failed to move parcels within the specified timeout.");
            }
        } catch (NotEnoughItemsException e) {
            System.out.println("Not enough items in the source locker.");
        }
    }
}

class LockerSource {
    private int id;
    private int itemCount;
    private ReentrantLock lock = new ReentrantLock();

    public LockerSource(int id) {
        this.id = id;
    }

    public void addItem() {
        lock.lock();
        try {
            itemCount++;
        } finally {
            lock.unlock();
        }
    }

    public void removeItem() {
        lock.lock();
        try {
            if (itemCount > 0) {
                itemCount--;
            }
        } finally {
            lock.unlock();
        }
    }
}

class LockerTarget {
    private int id;
    private ReentrantLock lock = new ReentrantLock();

    public LockerTarget(int id) {
        this.id = id;
    }
}

class ParcelMoverThread extends Thread {
    private final LockerSource sourceLocker;
    private final LockerTarget targetLocker;
    private final int quantityToMove;
    private final Duration timeoutDuration;
    private final TimeUnit timeUnit;
    private boolean result = false;

    public ParcelMoverThread(LockerSource sourceLocker, LockerTarget targetLocker, int quantityToMove, Duration timeoutDuration, TimeUnit timeUnit) {
        this.sourceLocker = sourceLocker;
        this.targetLocker = targetLocker;
        this.quantityToMove = quantityToMove;
        this.timeoutDuration = timeoutDuration;
        this.timeUnit = timeUnit;
    }

    @Override
    public void run() {
        try {
            acquireLocksAndMoveParcels();
        } catch (InterruptedException e) {
            e.printStackTrace();
        } catch (NotEnoughItemsException e) {
            System.out.println("Not enough items in the source locker.");
        }
    }

    private void acquireLocksAndMoveParcels() throws InterruptedException, NotEnoughItemsException {
        lockSourcesTargets();
        int movedCount = moveParcels(quantityToMove);
        if (movedCount != quantityToMove) {
            unlockSourcesTargets();
            Thread.sleep(timeoutDuration.toMillis(timeUnit));
            throw new TimeoutException("Timeout expired while moving parcels.");
        }
    }

    private void lockSourcesTargets() throws InterruptedException, NotEnoughItemsException {
        long startTime = System.currentTimeMillis();
        long timeoutInMillis = timeoutDuration.toMillis(timeUnit);

        while (!sourceLocker.lock.isLocked() || !targetLocker.lock.isLocked()) {
            if (System.currentTimeMillis() - startTime > timeoutInMillis) {
                break;
            }

