        Container container1 = new Container(elementCount);
        Container container2 = new Container(elementCount);

        int numElements = 5;
        long timeout = 5000L;
        Duration timeUnit = Duration.ofMillis(timeout);
        TimeUnit unit = ChronoUnit.MILLIS;

        executor.submit(new SwapTask(container1, container2, numElements, timeout, unit));
        executor.submit(new SwapTask(container2, container1, numElements, timeout, unit));

        executor.shutdown();
    }
}

class ElementCount {
    int count;

    void increment() {
        ++count;
    }

    void decrement() {
        --count;
    }
}

class Container {
    private final ElementCount elementCount;
    private int[] elements;

    public Container(ElementCount elementCount) {
        this.elementCount = elementCount;
        this.elements = new int[10];
    }

    public synchronized void addElement() {
        elementCount.increment();
        if (hasSufficientElements()) {
            swap(true, 0);
        }
    }

    public synchronized void removeElement() {
        elementCount.decrement();
        if (hasSufficientElements()) {
            swap(false, 0);
        }
    }

    private boolean hasSufficientElements() {
        return elementCount.get() > 0;
    }

    private void swap(boolean isAdd, int index) {
        if (isAdd) {
            --elementCount.get();
        } else {
            ++elementCount.get();
        }
        int temp = elements[index];
        elements[index] = 0;
        if (!isAdd) {
            elementCount.increment();
        }
    }
}

class SwapTask extends Callable<Boolean> {
    private final Container targetContainer;
    private final Container originContainer;
    private final int numElements;
    private final long timeout;
    private final TimeUnit unit;

    public SwapTask(Container targetContainer, Container originContainer, int numElements, long timeout, TimeUnit unit) {
        this.targetContainer = targetContainer;
        this.originContainer = originContainer;
        this.numElements = numElements;
        this.timeout = timeout;
        this.unit = unit;
    }

    @Override
    public Boolean call() throws InterruptedException, ExecutionException {
        Lock lock1 = targetContainer.new ReentrantLock();
        Lock lock2 = originContainer.new ReentrantLock();

        while (true) {
            long startTime = System.currentTimeMillis();
            long timeoutDuration = unit.toNanos(timeout);
            try {
                if (lock1.tryLock(timeout, TimeUnit.NANOSECONDS)) {
                    if (lock2.tryLock(timeout, TimeUnit.NANOSECONDS)) {
                        for (int i = 0; i < numElements; i++) {
                            targetContainer.removeElement();
                            originContainer.addElement();
                        }
                        return true;
                    } else {
                        lock2.unlock();
                    }
                } else {
                    break;
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }

            long elapsedTime = System.currentTimeMillis() - startTime;
            long remainingTimeout = unit.toNanos(timeout) - (System.currentTimeMillis() - startTime + 1);
            long randomDelay = (long) (Math.random() * (remainingTimeout > 0 ? remainingTimeout : 1));
            LockSupport.parkNanos(remainingTimeout - randomDelay);
        }

        return false;
    }
}

