    public boolean swap(int container1Size, int container2Size, int elementsToSwap, long timeout, TimeUnit timeUnit) {
        long startTime = System.currentTimeMillis();
        long endTime = startTime + timeout;

        int targetIndex = Math.min(container1Size - 1, elementsToSwap);
        int sourceIndex = Math.max(0, container2Size - elementsToSwap);

