import java.util.HashSet;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicInteger;

public class ServerStatusBeforeSplit {
    private final AtomicInteger vehicleCount = new AtomicInteger(0);
    private final AtomicInteger queryCount = new AtomicInteger(0);
    private final HashSet<String> vehicles;
    private final HashSet<String> queries;

    public ServerStatusBeforeSplit() {
        vehicles = new HashSet<>();
        queries = new HashSet<>();
    }

    public synchronized void addUser(String user) {
        vehicles.add(user);
        vehicleCount.incrementAndGet();
    }

    public synchronized void addQuery(String query) {
        queries.add(query);
        queryCount.incrementAndGet();
    }

    public synchronized String removeUser(String user) {
        boolean removed = vehicles.remove(user);
        if (removed) {
            vehicleCount.decrementAndGet();
        }
        return removed ? user : null;
    }

    public synchronized String removeQuery(String query) {
        boolean removed = queries.remove(query);
        if (removed) {
            queryCount.decrementAndGet();
        }
        return removed ? query : null;
    }

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        for (int i = 0; i < 2; i++) {
            executor.submit(new VehicleAdditionRunnable());
        }

        executor.shutdown();
    }

    private class VehicleAdditionRunnable implements Runnable {
        @Override
        public void run() {
            while (true) {
                try {
                    Thread.sleep(1000);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
                ServerStatusBeforeSplit.this.addUser("vehicle_" + vehicleCount.getAndIncrement());
            }
        }
    }
}

