    private static int channelTheGrimoire(List<Rune> candidateRunes) {
        int harmoniesCount = 0;
        RuneComparator comparator = new RuneComparator();

        ExecutorService executor = Executors.newFixedThreadPool(3);

        for (Rune rune : candidateRunes) {
            executor.execute(() -> {
