import java.util.concurrent.*;

public class CelestialCaravanTracker {
    private final ConcurrentHashMap<String, Starlight> catalog;

    public CelestialCaravanTracker(Map<String, Starlight> initialCatalog) {
        catalog = new ConcurrentHashMap<>(initialCatalog);
    }

    public Map<String, Starlight> getHavens() {
        return Collections.unmodifiableMap(catalog);
    }

    public Starlight getHaven(String glyph) {
        return catalog.get(glyph);
    }

