        Talisman talisman2 = new Talisman("Talisman 2", "This is the second talisman.");
        Talisman talisman3 = new Talisman("Talisman 3", "This is the third talisman.");

        SigilNode rootSigil = new SigilNode("Root Sigil", null);
        SigilNode leftSigil = new SigilNode("Left Sigil", null);
        SigilNode rightSigil = new SigilNode("Right Sigil", null);
        rootSigil.setLeft(leftSigil);
        rootSigil.setRight(rightSigil);

