        List<SigilNode> sigils = new ArrayList<>();
        sigils.add(new SigilNode("Sigil 1", talisman1));
        sigils.add(new SigilNode("Sigil 2", talisman2));
        sigils.add(new SigilNode("Sigil 3", talisman3));

        ConcurrentEnchantment concurrentEnchantment = new ConcurrentEnchantment();
        long startTime = System.currentTimeMillis();
        List<Future<Void>> futures = concurrentEnchantment.conjureSimultaneously(sigils);
        for (Future<Void> future : futures) {
            future.get();
        }
        long endTime = System.currentTimeMillis();
        System.out.println("Total time for simultaneous conjuration: " + (endTime - startTime) + "ms");
    }

    public List<SigilResult> weaveSequentially(List<SigilNode> sigils) {
        List<SigilResult> results = new ArrayList<>();
        for (SigilNode node : sigils) {
            long startTime = System.currentTimeMillis();
            SigilResult result = node.computeResult();
            results.add(result);
            long endTime = System.currentTimeMillis();
            System.out.println("Total time for sequential conjuration: " + (endTime - startTime) + "ms");
        }
        return results;
    }

    public List<SigilResult> weaveConcurrently(List<SigilNode> sigils) throws InterruptedException, ExecutionException {
        return weaveConcurrently(sigils, 2);
    }

    public List<SigilResult> weaveConcurrently(List<SigilNode> sigils, int maxThreads) throws InterruptedException, ExecutionException {
        BlockingQueue<SigilNode> queue = new LinkedBlockingQueue<>();
        List<SigilResult> results = new ArrayList<>();
        ThreadPoolExecutor executor = new ThreadPoolExecutor(1, maxThreads, 5000, TimeUnit.MILLISECONDS, queue);

