    private static void transferCrystals(VaultNode source, VaultNode target) {
        Lock lock = new ReentrantLock();
        lock.lock();
        try {
            int srcHash = source.getIdentityHashCode();
            int tgtHash = target.getIdentityHashCode();
            Lock secondaryLock = new ReentrantLock();

            if (srcHash == tgtHash) {
