public class MagicalOrbVault {
    private final Semaphore availableOrbs;
    private final Semaphore orbSlots;
    private int numOrbs;
    private int freeSlots;

    public MagicalOrbVault(int orbCapacity) {
        availableOrbs = new Semaphore(0);
        orbSlots = new Semaphore(orbCapacity);
        numOrbs = 0;
        freeSlots = orbCapacity;
    }

    public void put(Orb orb) throws InterruptedException {
        availableOrbs.acquire();
        orbSlots.acquire();
        synchronized (this) {
            numOrbs++;
            freeSlots--;
        }
    }

    public Orb take() throws InterruptedException {
        synchronized (this) {
            while (freeSlots == 0) {
                availableOrbs.release();
                orbSlots.acquire();
            }
            Orb orb = new Orb(numOrbs--, freeSlots++);
            return orb;
        }
