import java.util.concurrent.Semaphore;
import java.util.concurrent.atomic.AtomicInteger;

public class PotionLoop {
    private final Semaphore potionsAvailable = new Semaphore(0);
    private final AtomicInteger openSlots = new AtomicInteger(0);
    private int[] items;
    private int head;
    private int tail;

    public PotionLoop(int size) {
        items = new int[size];
    }

    public void put(int potion) {
        try {
            potionsAvailable.acquire();
            synchronized (this) {
                while (isFull()) {
                    wait();
                }
                items[tail] = potion;
                tail = (tail + 1) % items.length;
                openSlots.decrementAndGet();
                notify();
            }
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }

    public int take() {
        try {
            potionsAvailable.acquire();
            synchronized (this) {
                while (isEmpty()) {
                    wait();
                }
                int removed = items[head];
                head = (head + 1) % items.length;
                openSlots.incrementAndGet();
                notify();
                return removed;
            }
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        return -1; // Return default value to avoid compiler warning
    }

    public boolean isEmpty() {
        synchronized (this) {
            return head == tail;
        }
    }

    public boolean isFull() {
        synchronized (this) {
            return openSlots.get() == 0;
        }
    }

