import java.util.*;
import java.util.concurrent.locks.*;

public class CrystalCache {
    private final Map<String, String> relics;
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();
    private final Lock readLock = lock.readLock();
    private final Lock writeLock = lock.writeLock();

    public CrystalCache(Map<String, String> relics) {
        this.relics = Collections.synchronizedMap(new HashMap<>(relics));
    }

    public void put(String key, String value) {
        writeLock.lock();
        try {
            relics.put(key, value);
        } finally {
            writeLock.unlock();
        }
    }

    public String get(Object key) {
        readLock.lock();
        try {
            return relics.get(key);
        } finally {
            readLock.unlock();
        }
    }

    public int size() {
        readLock.lock();
        try {
            return relics.size();
        } finally {
            readLock.unlock();
        }
    }

    public boolean isEmpty() {
        readLock.lock();
        try {
            return relics.isEmpty();
        } finally {
            readLock.unlock();
        }
    }

    public boolean containsKey(Object key) {
        readLock.lock();
        try {
            return relics.containsKey(key);
        } finally {
            readLock.unlock();
        }
    }

    public boolean containsValue(Object value) {
        readLock.lock();
        try {
            return relics.containsValue(value);
        } finally {
            readLock.unlock();
        }
    }

    public void clear() {
        writeLock.lock();
        try {
            relics.clear();
        } finally {
            writeLock.unlock();
        }
    }

    public static void main(String[] args) {
        Map<String, String> relics = new HashMap<>();
        CrystalCache cache = new CrystalCache(relics);

        // Add 4 threads to the thread pool
        ExecutorService service = Executors.newFixedThreadPool(4);

        // Create tasks for put and get operations
        service.submit(() -> {
            for (int i = 0; i < 10; i++) {
                cache.put("Key" + i, "Value" + i);
            }
        });

        service.submit(() -> {
