import java.util.*;
import java.util.concurrent.locks.*;
import java.io.IOException;

public class EnchantedRegistry<K, V> {
    private final Map<K, V> map;
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();
    private final ReentrantReadWriteLock.ReadLock readLock = lock.readLock();
    private final ReentrantReadWriteLock.WriteLock writeLock = lock.writeLock();

    public EnchantedRegistry(Map<K, V> map) {
        this.map = map;
    }

    public void put(K key, V value) {
        writeLock.lock();
        try {
            map.put(key, value);
        } finally {
            writeLock.unlock();
        }
    }

    public V get(Object key) {
        readLock.lock();
        try {
            return map.get(key);
        } finally {
            readLock.unlock();
        }
    }

    public int size() {
        readLock.lock();
        try {
            return map.size();
        } finally {
            readLock.unlock();
        }
    }

    public boolean isEmpty() {
        readLock.lock();
        try {
            return map.isEmpty();
        } finally {
            readLock.unlock();
        }
    }

    public boolean containsKey(Object key) {
        readLock.lock();
        try {
            return map.containsKey(key);
        } finally {
            readLock.unlock();
        }
    }

    public boolean containsValue(Object value) {
        readLock.lock();
        try {
            return map.containsValue(value);
        } finally {
            readLock.unlock();
        }
    }

    public void clear() {
        writeLock.lock();
        try {
            map.clear();
        } finally {
            writeLock.unlock();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Map<Integer, Integer> artifacts = new HashMap<>();
        EnchantedRegistry<Integer, Integer> registry = new EnchantedRegistry<>(artifacts);

        Thread crafter1 = new Thread(() -> {
            for (int i = 0; i < 10; i++) {
                registry.put(i, i * 2);
                Thread.sleep(100);
            }
        });

        Thread crafter2 = new Thread(() -> {
            for (int i = 10; i < 20; i++) {
                registry.put(i, i * 2);
                Thread.sleep(100);
            }
        });

        Thread observer1 = new Thread(() -> {
            while (true) {
                try {
                    System.out.println("Observer 1: " + registry.get(0));
                    Thread.sleep(1000);
                } catch (InterruptedException e) {
                    e.printStackTrace();
