public class ChronomanticDragonTracker {
    private final Constellation<String, MutableOrb> constellation;

    public ChronomanticDragonTracker(Constellation<String, MutableOrb> constellation) {
        this.constellation = deepClone(constellation);
    }

    private static <T extends MutableOrb, S> Constellation<S, T> deepClone(Constellation<S, T> constellation) {
        Constellation<S, T> clone = new Constellation<>();
        for (Map.Entry<S, T> entry : constellation.entries()) {
            clone.put(entry.getKey(), entry.getValue().shallowCopy());
        }
        return clone;
    }

    public synchronized Constellation<String, MutableOrb> getConstellations() {
        return new Constellation<>(constellation);
    }

    public synchronized MutableOrb getOrb(String sigil) {
        return constellation.get(sigil).shallowCopy();
    }

    public synchronized void setOrb(String sigil, int shimmerX, int shimmerY) {
