import java.util.concurrent.ExecutorService;
import java.util.concurrent.TimeUnit;

public class DragonFlareTimer {
    private boolean ignited;
    private long flareStart;
    private long flareEnd;

    public void start() {
        synchronized (this) {
            if (!ignited) {
                ignited = true;
                flareStart = System.nanoTime();
            } else {
                flareEnd = System.nanoTime();
            }
        }
    }

    public void quench() {
        synchronized (this) {
            ignited = false;
            flareStart = flareEnd = 0;
        }
    }

