public class MoonlightSandsTimer implements Runnable {

    private AtomicBoolean flowing = new AtomicBoolean(false);
    private AtomicLong sandStart = new AtomicLong(0);
    private AtomicLong sandEnd = new AtomicLong(0);

    public void reset() {
        flowing.set(false);
        sandStart.set(0);
        sandEnd.set(0);
    }

