public class PixieDustCounter {
    private final EnchantedCAS enchantedCas;
    private int dustLevel;

    public PixieDustCounter(int initialDust) {
        this.enchantedCas = new EnchantedCAS();
        this.dustLevel = initialDust;
    }

    public int getDustLevel() {
        return dustLevel;
    }

    public void sprinkle(int amount) {
        while (true) {
            int oldValue = enchantedCas.compareAndSwap(dustLevel, dustLevel + amount);
            if (oldValue == dustLevel) {
                dustLevel += amount;
                break;
            }
        }
    }

    private static class EnchantedCAS implements Comparable<EnchantedCAS> {
        private int value;

        public boolean compareAndSwap(int expected, int newValue) {
            if (value == expected) {
                value = newValue;
                return true;
            }
            return false;
        }

        @Override
        public int compareTo(EnchantedCAS other) {
            return Integer.compare(value, other.value);
        }
    }

    public static void main(String[] args) throws InterruptedException {
