    public static boolean transfer(Account source, Account destination, DollarAmount amount, long timeout, TimeUnit timeUnit) {
        ReentrantLock lock1 = new ReentrantLock();
        ReentrantLock lock2 = new ReentrantLock();
        ReentrantLock lock3 = new ReentrantLock();

        source.lock();
        destination.lock();

        long startTime = System.currentTimeMillis();
        long endTime = startTime + timeout;

        while (source.getBalance() < amount.getValue()) {
            if (!lock3.tryLock(timeout, timeUnit)) {
                return false;
            }

            int attempts = 0;
            double randomFactor = Math.random();

            while (attempts < 2 && !lock1.isHeldByCurrentThread()) {
                if (lock2.tryLock(timeout, timeUnit)) {
                    break;
                }
                attempts++;
                try {
                    Thread.sleep((long) (10L + randomFactor * 10L));
                } catch (InterruptedException e) {
                    e.printStackTrace();
