public class BoundedBuffer {
    private final int CAPACITY;
    private int head;
    private int tail;
    private Semaphore availableSlots;
    private Semaphore itemsTaken;

    public BoundedBuffer(int capacity) {
        CAPACITY = capacity;
        head = 0;
        tail = 0;
        availableSlots = new Semaphore(capacity);
        itemsTaken = new Semaphore(0);
    }

    public void put(E x) throws InterruptedException {
        if (isFull()) {
            availableSlots.acquire();
        }
        synchronized (this) {
            while (tail == CAPACITY) {
                itemsTaken.release();
                availableSlots.acquire();
            }
            buffer[head] = x;
            head = (head + 1) % CAPACITY;
            if (head == tail) {
                availableSlots.release();
            }
        }
    }

    public E take() throws InterruptedException {
        if (isEmpty()) {
            itemsTaken.acquire();
        }
        synchronized (this) {
            while (head == tail) {
                availableSlots.release();
                itemsTaken.acquire();
            }
            E result = buffer[tail];
            tail = (tail + 1) % CAPACITY;
            if (tail == head) {
                availableSlots.release();
            }
            return result;
        }
    }

    public boolean isEmpty() {
        synchronized (this) {
            return tail == head;
        }
    }

    public boolean isFull() {
        synchronized (this) {
            return tail == (CAPACITY - 1);
        }
    }

    private static final Semaphore[] semaphores = new Semaphore[2];

    public static void main(String[] args) throws InterruptedException {
        int capacity = 5;
        BoundedBuffer<Integer> buffer = new BoundedBuffer<>(capacity);
        Thread producer = new Thread(() -> {
            for (int i = 0; i < 3; i++) {
                buffer.put(i);
            }
        });
        Thread consumer = new Thread(() -> {
            for (int i = 0; i < 3; i++) {
                buffer.take();
            }
        });
        producer.start();
        consumer.start();
        producer.join();
        consumer.join();
    }
}

import java.util.concurrent.Semaphore;
import java.util.concurrent.atomic.AtomicInteger;

public class BoundedBuffer {
    private int capacity;
    private int count;
    private AtomicInteger availableItems;
    private AtomicInteger remainingSpace;

    public BoundedBuffer(int capacity) {
        this.capacity = capacity;
        this.count = 0;
        this.availableItems = new AtomicInteger(0);
        this.remainingSpace = new AtomicInteger(capacity);
    }

    public void put(Object x) throws InterruptedException {
        while (remainingSpace.get() == 0) {
            availableItems.acquire();
        }
        remainingSpace.decrementAndGet();
        synchronized (this) {
            count++;
            if (count > capacity) {
                throw new IllegalStateException("Buffer is full");
            }
            this.notifyAll();
        }
    }

    public Object take() throws InterruptedException {
        while (availableItems.get() == 0) {
            synchronized (this) {
                this.wait();
            }
        }
        availableItems.incrementAndGet();
        remainingSpace.incrementAndGet();
        return null;
    }

    public boolean isEmpty() {
        return count == 0;
    }

    public boolean isFull() {}
}

import java.util.concurrent.Semaphore;
import java.util.concurrent.atomic.AtomicInteger;

public class BoundedBuffer {
    private int maxSize;
    private AtomicInteger itemsInBuffer;
    private Semaphore semaphore;
    private Object[] buffer;

    public BoundedBuffer(int maxSize) {
        this.maxSize = maxSize;
        this.itemsInBuffer = new AtomicInteger(0);
        this.semaphore = new Semaphore(0);
        this.buffer = new Object[maxSize];
    }

    public void put(Object e) throws InterruptedException {
        semaphore.acquire();
        if (itemsInBuffer.get() < maxSize) {
            buffer[itemsInBuffer.get()] = e;
            itemsInBuffer.incrementAndGet();
        } else {
            semaphore.release();
            throw new IllegalStateException("Buffer is full");
        }
    }

    public Object take() throws InterruptedException {
        semaphore.acquire();
        if (itemsInBuffer.get() > 0) {
            itemsInBuffer.decrementAndGet();
            Object result = buffer[0];
            for (int i = 1; i < maxSize; i++) {
                buffer[i] = buffer[i + 1];
            }
            return result;
        } else {
            semaphore.release();
            throw new IllegalStateException("Buffer is empty");
        }
    }

    public boolean isEmpty() {
        return itemsInBuffer.get() == 0;
    }

    public boolean isFull() {
        return itemsInBuffer.get() >= maxSize;
    }

    public static void main(String[] args) throws InterruptedException {
        int maxSize = 5;
        BoundedBuffer buffer = new BoundedBuffer(maxSize);
        Semaphore semaphore = new Semaphore(1);

        Thread producer = new Thread(() -> {
            for (int i = 0; i < 3; i++) {
                buffer.put("Item " + (i + 1));
                semaphore.release();
                Thread.sleep(1000);
            }
        });

        Thread consumer = new Thread(() -> {
            for (int i = 0; i < 3; i++) {
                buffer.take();
                semaphore.acquire();
            }
        });

        producer.start();
        consumer.start();
        producer.join();
        consumer.join();
    }
}

