class Server {
    private final ServerSocket serverSocket;
    private volatile Cache cache;

    public Server() throws IOException {
        serverSocket = new ServerSocket(8080);
        cache = new Cache();
    }

    public void start() throws IOException {
        System.out.println("Server started");
        acceptConnections();
    }

    private void acceptConnections() throws IOException {
        while (true) {
            Socket socket = serverSocket.accept();
            new Thread(() -> handleRequest(socket)).start();
        }
    }

    private void handleRequest(Socket socket) {
        try (InputStream in = socket.getInputStream();
             OutputStream out = socket.getOutputStream()) {
            String request = new Scanner(in).useDelimiter("\\A").next();
            JsonObject jsonObject = parseJson(request);

            BigInteger value = cache.getOrCompute(jsonObject);
            sendResponse(out, value);
        } catch (IOException | InterruptedException e) {
            System.err.println("Error in handleRequest: " + e.getMessage());
        }
    }

    private JsonObject parseJson(String json) {
        return JsonObject.readFrom(new StringReader(json));
    }

    private void sendResponse(OutputStream out, BigInteger value) throws IOException {
        JsonObject response = JsonObject.create().put("value", value);
        String jsonResponse = response.toString();
        out.write(jsonResponse.getBytes());
        out.flush();
    }

    public void stop() {
        serverSocket.close();
    }
}

class Cache {
    private final BigInteger[] cache;

    public Cache() {
        cache = new BigInteger[1];
    }

    public BigInteger get(JsonObject json) {
        for (int i = 0; i < cache.length; i++) {
            if (cache[i].equals(json.get("value"))) {
                return cache[i];
            }
        }
        return compute(json);
    }

    public BigInteger getOrCompute(JsonObject json) {
        for (int i = 0; i < cache.length; i++) {
            if (cache[i].equals(json.get("value"))) {
                return cache[i];
            }
        }
        cache[0] = compute(json);
        return cache[0];
    }

    private BigInteger compute(JsonObject json) {
        return new BigInteger(json.get("value").toString());
    }
}

