class Task implements Runnable {
    private final Cache<BigInteger, BigInteger> cache;

    public Task(Cache<BigInteger, BigInteger> cache) {
        this.cache = cache;
    }

    @Override
    public void run() {
        BigInteger input = RandomUtils.nextBigInteger(0, 2);
        while (true) {
            BigInteger result = compute(input);
            if (!cache.get(input).equals(result)) {
                cache.put(input, result);
            }
            try {
                Thread.sleep(100);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    }

    private BigInteger compute(BigInteger input) {
        return input;
    }
}

