    static class FixedThreadPool {
        private final ThreadGroup group;
        private final AtomicInteger activeCount;
        private final int maxThreads;

        public FixedThreadPool(int maxThreads, ThreadGroup group) {
            this.group = group;
            this.activeCount = new AtomicInteger(0);
            this.maxThreads = maxThreads;
        }

        public void execute(Runnable task) {
            if (activeCount.incrementAndGet() > maxThreads) {
                throw new IllegalStateException("Exceeded maximum thread limit");
            }

            Thread thread = new Thread(task, "ConcurrentApp-" + THREAD_COUNTER.get());
            thread.setDaemon(true);
            thread.start();
        }

        public void shutdown() {
            while (!Thread.currentThread().isInterrupted()) {
                Thread[] threads = new Thread[group.activeCount()];
                group.enumerate(threads);

                for (Thread t : threads) {
                    if (!t.isDaemon()) {
                        try {
                            t.join();
                        } catch (InterruptedException e) {
                            LOGGER.severe("Error joining thread: " + t.getName());
                        }
                    }
                }
            }
        }
    }

