    private static final int N_LOCKS = 16;
    private Node[] buckets;
    private Lock[] locks;

    public StripedMap(int size) {
        buckets = new Node[size];
        locks = new Lock[N_LOCKS];
        for (int i = 0; i < N_LOCKS; i++) {
            locks[i] = new ReentrantLock();
        }
    }

    public int hashIndex(String key) {
        int h = key.hashCode() % buckets.length;
        return h;
    }

    public String get(String key) {
        int index = hashIndex(key);
        Lock lock = locks[index % N_LOCKS];
        lock.lock();
        try {
            Node node = buckets[index];
            if (node == null) {
                return null;
            }
            if (node.key.equals(key)) {
                return node.value;
            }
            Node prev = node.prev;
            while (prev != null && !prev.key.equals(key)) {
                prev = prev.prev;
            }
            if (prev != null) {
                buckets[index] = prev;
                return prev.value;
            }
            return null;
        } finally {
            lock.unlock();
        }
