import java.math.BigInteger;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class ImmutableCache {
    private final BigInteger number;
    private final BigInteger[] factors;

    public ImmutableCache(BigInteger number, BigInteger[] factors) {
        this.number = number;
        this.factors = factors.clone();
    }

    public BigInteger[] getFactors() throws ExecutionException, InterruptedException {
        if (number.equals(BigInteger.ZERO)) {
            return new BigInteger[0];
        }

        if (factors == null) {
            throw new IllegalStateException("Cache not initialized");
        }

        return factors.clone();
    }

    public static void main(String[] args) throws ExecutionException, InterruptedException {
        int numThreads = 2;
        int maxFactors = 2;
        int numberOfCaches = 10;

        ImmutableCache cache = new ImmutableCache(BigInteger.ZERO, null);

        ExecutorService executor = Executors.newFixedThreadPool(numThreads + 1);

        for (int i = 0; i < numberOfCaches; i++) {
            Callable<Void> task = () -> {
                BigInteger randomNumber = getRandomBigInteger(maxFactors, false);
                BigInteger[] factors = findFactors(randomNumber);
                cache.number = randomNumber;
                cache.factors = factors;
                return null;
            };

            executor.submit(task);
        }

        executor.shutdown();
    }

    private static BigInteger[] findFactors(BigInteger number) {
        BigInteger[] factors = new BigInteger[2];

        for (BigInteger divisor = BigInteger.ONE; divisor.compareTo(number) <= 0; divisor = divisor.add(BigInteger.ONE)) {
            if (number.remainder(divisor).equals(BigInteger.ZERO)) {
                factors[0] = divisor;
                factors[1] = number.divide(divisor);
                break;
            }
        }

        return factors;
    }

    private static BigInteger getRandomBigInteger(int maxValue, boolean positive) {
        int range = 2 + (positive ? 0 : 1);
        Random random = new Random();
        int value = random.nextInt(range);
        return BigInteger.valueOf(value).multiply(BigInteger.TEN.pow(maxValue));
    }
}

