    public TransactionHandler(Account accountA, Account accountB, double transferAmount) {
        this.accountA = accountA;
        this.accountB = accountB;
        this.transferAmount = transferAmount;
    }

    @Override
    public void run() {
        synchronized (accountA) {
            synchronized (accountB) {
                if (accountA.getBalance().getValue() >= transferAmount && accountB.getBalance().getValue() < transferAmount) {
                    accountA.getBalance().setValue(accountA.getBalance().getValue() - transferAmount);
