    public static void main(String[] args) {
        List<Account> accounts = new ArrayList<>();
        accounts.add(new Account(1000, "A"));
        accounts.add(new Account(2000, "B"));
        accounts.add(new Account(3000, "C"));

        System.out.println("Initial Balances:");
        for (Account account : accounts) {
            System.out.println(account);
        }

        ExecutorService executor = Executors.newFixedThreadPool(3);

        Runnable transferTaskA = () -> {
            Account a = new Account(1000, "A");
            Account b = new Account("B", 2000);
            Account c = new Account("C", 3000);

            lockAndTransfer(a, b, c);
        };

        Runnable transferTaskB = () -> {
            Account a = new Account(1000, "A");
            Account b = new Account("B", 2000);
            Account c = new Account("C", 3000);

            lockAndTransfer(b, a, c);
        };

        Runnable transferTaskC = () -> {
            Account a = new Account(1000, "A");
            Account b = new Account("B", 2000);
            Account c = new Account("C", 3000);

            lockAndTransfer(c, a, b);
        };

        executor.submit(transferTaskA);
        executor.submit(transferTaskB);
        executor.submit(transferTaskC);

        executor.shutdown();
    }

    private static void lockAndTransfer(Account from, Account to, Account other) {
        synchronized (from) {
            if (from.getBalance() >= 100) {
                from.withdraw(100);
                to.deposit(100);
                other.deposit(100);
            } else {
                throw new InsufficientFundsException("Insufficient funds in account " + from.getName());
            }
        }
    }
}

