executor.submit(() -> {
for (int j = 0; j < 5; j++) {
int value = threadId * 10 + j;
stack.push(value);
System.out.println(Thread.currentThread().getName() + " pushed: " + value);
}

for (int j = 0; j < 5; j++) {
Integer value = stack.pop();
System.out.println(Thread.currentThread().getName() + " popped: " + value);
