public class DelegatingVehicleTracker {
    private final Map<String, VehicleLocation> locations;
    private final AtomicInteger nextId;

    public DelegatingVehicleTracker() {
        this.locations = new ConcurrentHashMap<>();
        this.nextId = new AtomicInteger(1);
    }

    public void addVehicle(String vehicleId, double latitude, double longitude) {
        if (vehicleId != null && !locations.containsKey(vehicleId)) {
            VehicleLocation location = new VehicleLocation(nextId.getAndIncrement(), vehicleId, latitude, longitude);
            locations.put(vehicleId, location);
        }
    }

    public void setVehicleLocation(String vehicleId, double latitude, double longitude) {
        if (vehicleId != null && !locations.containsKey(vehicleId)) {
            addVehicle(vehicleId, latitude, longitude);
        } else if (locations.containsKey(vehicleId)) {
            VehicleLocation location = locations.get(vehicleId);
            location.setLatitude(latitude);
            location.setLongitude(longitude);
        }
    }

    public Map<String, Double> getVehicleLocations() {
        return locations.values().stream()
                .filter(Objects::nonNull)
                .collect(Collectors.toMap(VehicleLocation::getVehicleId, VehicleLocation::getLatitude));
