        int pairs = 0;

        for (int i = 0; i < animals.size(); i++) {
            if (i > 0 && animals.get(i).getSpecies() == animals.get(i - 1).getSpecies()) {
                continue;
            }
            Animal first = animals.get(i);
            for (int j = i + 1; j < animals.size(); j++) {
                if (j > i + 1 && animals.get(j).getSpecies() == animals.get(j - 1).getSpecies()) {
                    continue;
                }
                Animal second = animals.get(j);
                if (first.getGender() != second.getGender()) {
