import java.util.*;
import java.util.concurrent.*;

public class Ark {
    private List<Animal> animals;

    public Ark(List<Animal> animals) {
        this.animals = animals;
    }

    public void loadTheArk() throws InterruptedException, ExecutionException {
        Comparator<Animal> comparator = (a, b) -> a.species.compareTo(b.species) * 100 + a.gender - b.gender;
        animals.sort(comparator);
        ExecutorService executor = Executors.newFixedThreadPool(2);
        int pairs = executeTasks(executor, animals);
        executor.shutdown();
        System.out.println("Number of valid pairs: " + pairs);
    }

    private int executeTasks(ExecutorService executor, List<Animal> animals) throws InterruptedException, ExecutionException {
        int pairs = 0;
        for (int i = 0; i < Math.min(animals.size(), 3); i++) {
            if (i >= animals.size()) {
                break;
            }
            Animal a = animals.get(i);
            List<Animal> group = new ArrayList<>();
            for (int j = i + 1; j < Math.min(animals.size(), i + 3); j++) {
                if (j >= animals.size()) {
                    break;
                }
                Animal b = animals.get(j);
                if (a.species == b.species && a.gender != b.gender) {
                    group.add(b);
                }
            }
            if (!group.isEmpty()) {
                pairs += group.size();
                executor.submit(() -> {
                    new Pair(group.get(0), group.get(1));
                });
            }
        }
        return pairs;
    }
}

