import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.time.Duration;
import java.time.temporal.ChronoUnit;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicBoolean;

public class PrimeGenerator {
    private static final int NUMBER_OF_PRIMES = 10;
    private static final long WAIT_TIME = Duration.ofSeconds(1).toMillis();
    private static final Random RANDOM = new Random();
    private static AtomicBoolean isCancelled = new AtomicBoolean(false);
    private static List<Integer> primes = new ArrayList<>();

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        long startTime = System.currentTimeMillis();
        executor.submit(() -> {
            for (int i = 0; i < NUMBER_OF_PRIMES && !isCancelled.get();) {
                int number = RANDOM.nextInt(100) + 2;
                if (isPrime(number)) {
                    primes.add(number);
                    i++;
                }
            }
        });

        executor.submit(() -> {
            while (!isCancelled.get()) {
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
                if (System.currentTimeMillis() - startTime >= WAIT_TIME) {
                    isCancelled.set(true);
                }
            }
        });

        executor.shutdown();

        if (!executor.isTerminated()) {
            throw new IllegalStateException("ExecutorService did not terminate");
        }

        System.out.println("Found primes: " + primes);
    }

    private static boolean isPrime(int number) {
        if (number <= 1) return false;
        for (int divisor = 2; divisor < number; divisor++) {
            if (number % divisor == 0) return false;
        }
        return true;
    }
}

