    public static Future<List<Integer>> findPrimes(int numPrimes, long durationMs) {
        List<Integer> primes = new ArrayList<>();
        int limit = (int)(numPrimes * Math.sqrt(numPrimes));
        int lastChecked = 0;
        int prime = 2;

        boolean isCancelled = false;

        return ExecutorService.newFixedThreadPool(1).submit(() -> {
            while (!isCancelled) {
                if (prime > limit) {
                    break;
                }
                for (int i = lastChecked; i < prime; i++) {
                    if (prime % i == 0) {
                        break;
                    }
                    primes.add(prime);
                    lastChecked = prime;
                    prime++;
                }
                TimeUnit.MILLISECONDS.sleep(10);
            }
            return primes;
        });
    }
}

