    public List<Element> processTreeSequential(Node root) {
        List<Element> results = new ArrayList<>();
        processNodeSequential(root, results);
        return results;
    }

    public void processNodeSequential(Node node, List<Element> results) {
        if (node.isLeaf()) {
            results.add(node);
        } else {
            for (Node child : node.getChildren()) {
                processNodeSequential(child, results);
            }
        }
    }

    public List<Element> processTreeParallel(Node root) throws InterruptedException {
        List<Future<List<Element>>> futures = new ArrayList<>();
        int threadPoolSize = 2;
        ExecutorService executor = Executors.newFixedThreadPool(threadPoolSize);

        for (int i = 0; i < threadPoolSize; i++) {
            Future<List<Element>> future = executor.submit(() -> {
                List<Element> localResults = new ArrayList<>();
                processNodeParallel(root, localResults);
                return localResults;
            });
            futures.add(future);
        }

        List<List<Element>> resultsFutures = executor.invokeAll(futures);
        List<Element> results = new ArrayList<>();
        for (List<Element> futureResult : resultsFutures) {
            results.addAll(futureResult);
        }
        return results;
    }

    public void processNodeParallel(Node node, List<Element> results) throws InterruptedException {
        if (node.isLeaf()) {
            synchronized (results) {
                results.add(node);
            }
        } else {
            for (Node child : node.getChildren()) {
                processNodeParallel(child, results);
            }
        }
    }
}

