import java.util.Map;
import java.util.concurrent.ReadWriteLock;
import java.util.concurrent.ReentrantReadWriteLock;
import java.util.concurrent.locks.Lock;

public class ReadWriteMap<K, V> {
    private final Map<K, V> map;
    private final ReadWriteLock lock = new ReentrantReadWriteLock();
    private final Lock readLock = lock.readLock();
    private final Lock writeLock = lock.writeLock();

    public ReadWriteMap(Map<K, V> map) {
        this.map = map;
    }

    public V get(Object key) {
        try (Lock read = readLock) {
            return map.get(key);
        }
    }

    public boolean isEmpty() {
        try (Lock read = readLock) {
            return map.isEmpty();
        }
    }

    public int size() {
        try (Lock read = readLock) {
            return map.size();
        }
    }

    public boolean containsKey(Object key) {
        try (Lock read = readLock) {
            return map.containsKey(key);
        }
    }

    public boolean containsValue(Object value) {
        try (Lock read = readLock) {
            return map.containsValue(value);
        }
    }

    public V put(K key, V value) {
        try (Lock write = writeLock) {
            return map.put(key, value);
        }
    }

    public V remove(Object key) {
        try (Lock write = writeLock) {
            return map.remove(key);
        }
    }

    public void putAll(Map<? extends K, ? extends V> m) {
        try (Lock write = writeLock) {
            map.putAll(m);
        }
    }

    public void clear() {
        try (Lock write = writeLock) {
            map.clear();
        }
    }

    public static void main(String[] args) {
        Map<Integer, Integer> originalMap = new HashMap<>();
        ReadWriteMap<Integer, Integer> readWriteMap = new ReadWriteMap<>(originalMap);

        Thread t1 = new Thread(() -> {
            for (int i = 0; i < 2; i++) {
                System.out.println("Thread-1: " + readWriteMap.get(i));
            }
        });

        Thread t2 = new Thread(() -> {
            for (int i = 0; i < 2; i++) {
                System.out.println("Thread-2: " + readWriteMap.containsKey(i));
            }
        });

        Thread t3 = new Thread(() -> {
            for (int i = 0; i < 2; i++) {
                readWriteMap.put(i, i * 2);
            }
        });

        t1.start();
        t2.start();
        t3.start();
    }
}

